Date:   Sun Apr 30 13:25:16 2017 +0200

    gnutls_pkcs12_simple_parse: set to null vars after deinitialization

    This avoids having the variables being deinitialized twice during
    cleanup.

    Signed-off-by: Nikos Mavrogiannopoulos <nmav@redhat.com>

diff --git a/lib/x509/pkcs12.c b/lib/x509/pkcs12.c
index 16a015cb7..2b7b8d640 100644
--- a/lib/x509/pkcs12.c
+++ b/lib/x509/pkcs12.c
@@ -1593,233 +1593,237 @@ gnutls_pkcs12_simple_parse(gnutls_pkcs12_t p12,
        if (privkey_ok == 0) {  /* no private key */
                gnutls_assert();
                return GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
        }

        /* now find the corresponding certificate
         */
        idx = 0;
        bag = NULL;
        for (;;) {
                ret = gnutls_pkcs12_bag_init(&bag);
                if (ret < 0) {
                        bag = NULL;
                        gnutls_assert();
                        goto done;
                }

                ret = gnutls_pkcs12_get_bag(p12, idx, bag);
                if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE) {
                        gnutls_pkcs12_bag_deinit(bag);
                        bag = NULL;
                        break;
                }
                if (ret < 0) {
                        gnutls_assert();
                        goto done;
                }

                ret = gnutls_pkcs12_bag_get_type(bag, 0);
                if (ret < 0) {
                        gnutls_assert();
                        goto done;
                }

                if (ret == GNUTLS_BAG_ENCRYPTED) {
                        ret = gnutls_pkcs12_bag_decrypt(bag, password);
                        if (ret < 0) {
                                gnutls_assert();
                                goto done;
                        }
                }

                elements_in_bag = gnutls_pkcs12_bag_get_count(bag);
                if (elements_in_bag < 0) {
                        gnutls_assert();
                        goto done;
                }

                for (i = 0; i < (unsigned)elements_in_bag; i++) {
                        int type;
                        gnutls_datum_t data;
                        gnutls_x509_crt_t this_cert;

                        type = gnutls_pkcs12_bag_get_type(bag, i);
                        if (type < 0) {
                                gnutls_assert();
                                goto done;
                        }

                        ret = gnutls_pkcs12_bag_get_data(bag, i, &data);
                        if (ret < 0) {
                                gnutls_assert();
